def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 700:
                rich_opp += 1
            if opp.get('hp', 10) <= 4 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(bid)

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    supply_pressure = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    base = 18.0 + 18.0 * supply_pressure

    if supply <= 16:
        base += 10.0
    elif supply >= 23:
        base -= 5.0

    if no_water >= 2:
        base = max(base, 66.0)
    elif no_water >= 1:
        base = max(base, 46.0)

    if hp <= 3:
        base = max(base, 64.0)
    elif hp <= 5:
        base = max(base, 48.0)

    if highest_prev >= 100:
        if hp >= 6 and no_water == 0 and supply >= 19:
            base = min(base, 24.0)
        else:
            base = max(base, 52.0)
    elif highest_prev >= 85:
        if hp >= 7 and no_water == 0:
            base = min(base, 26.0)
        else:
            base = max(base, highest_prev * 0.62)
    elif highest_prev > 0:
        target = avg_prev + 2.5
        if supply <= 17 or no_water >= 1 or hp <= 5:
            base = max(base, target)
        else:
            base = min(max(base, target * 0.9), 42.0)

    if rich_opp >= 2 and supply <= 17 and hp >= 6 and no_water == 0:
        base = min(base, 28.0)

    days_left = max(0, 10 - day)
    reserve_target = days_left * 22.0
    affordable_cap = max(0.0, budget - reserve_target)
    if no_water >= 1 or hp <= 4:
        affordable_cap = budget

    bid = min(base, budget)
    if affordable_cap > 0:
        bid = min(bid, max(affordable_cap, 16.0))

    if (hp <= 3 or no_water >= 2) and budget > 0:
        bid = max(bid, min(budget, 68.0))

    if bid < 0:
        bid = 0.0
    return float(round(min(bid, budget), 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', (MIN_SUPPLY + MAX_SUPPLY) / 2.0))
    day = day_context.get('day', 0)

    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append(o)

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids for immediate reaction
    prev_bids = []
    for o in alive:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate rival pressure from yesterday
    if prev_bids:
        avg_bid = sum(prev_bids) / float(len(prev_bids))
        max_prev = max(prev_bids)
    else:
        avg_bid = DAILY_SALARY * 0.6
        max_prev = avg_bid

    # Supply tightness: if supply is low, water is scarce -> increase bid
    # supply_needed_factor ~ how many water units can be bought relative to our requirement
    # (We only use it as a monotone heuristic.)
    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY + 1e-9)  # 0..1-ish

    # Base bid targets: slightly under yesterday average if healthy, otherwise near/above max_prev.
    if hp <= 2.0 or no_water_days >= 2:
        target = max_prev * (0.98 - 0.1 * scarcity)  # urgent: match top pressure
    elif hp <= 4.0:
        target = avg_bid * (1.02 - 0.15 * scarcity)
    else:
        # healthy: try to win at a discount
        target = avg_bid * (0.92 - 0.12 * scarcity)

    # Also cap by a fraction of salary to avoid bankruptcy
    # If supply is very tight, allow paying more.
    salary_cap = DAILY_SALARY * (0.55 + 0.35 * scarcity)
    target = min(target, salary_cap)

    # Ensure we don't bid more than budget
    bid = min(budget, target)

    # If budget is tiny, still bid something non-negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)
